-- OctaLedger schema, migration 0001: initial tables.
--
-- Conventions
--   * Primary keys are random UUID strings generated by the application.
--   * Timestamps are UTC text in the FIXED-WIDTH form 'YYYY-MM-DDTHH:MM:SS.ffffffZ'
--     so that plain string comparison equals chronological comparison.
--   * Booleans are INTEGER 0/1 guarded by CHECK constraints.
--   * Originals are never overwritten silently: changes to sessions are recorded in
--     `corrections`, deletions in `audit_log`.
--   * Retention: devices, activities and projects that are referenced by events or
--     sessions cannot be deleted (ON DELETE RESTRICT); archive them instead.
--
-- Migrations run inside one transaction each; do not put BEGIN/COMMIT in this file.

CREATE TABLE devices (
    id               TEXT PRIMARY KEY,
    alias            TEXT NOT NULL CHECK (length(alias) BETWEEN 1 AND 100),
    platform_address TEXT,
    model            TEXT,
    firmware         TEXT,
    created_at       TEXT NOT NULL
);
CREATE UNIQUE INDEX ux_devices_alias ON devices (alias COLLATE NOCASE);

CREATE TABLE activities (
    id       TEXT PRIMARY KEY,
    name     TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    color    TEXT NOT NULL CHECK (color GLOB '#[0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F]'),
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
);
-- Names are unique among non-archived activities (case-insensitive).
CREATE UNIQUE INDEX ux_activities_name ON activities (name COLLATE NOCASE) WHERE archived = 0;

CREATE TABLE projects (
    id       TEXT PRIMARY KEY,
    name     TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    color    TEXT NOT NULL CHECK (color GLOB '#[0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F]'),
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
);
CREATE UNIQUE INDEX ux_projects_name ON projects (name COLLATE NOCASE) WHERE archived = 0;

CREATE TABLE face_mappings (
    device_id   TEXT NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    face        INTEGER NOT NULL CHECK (face BETWEEN 1 AND 8),
    activity_id TEXT REFERENCES activities (id) ON DELETE RESTRICT,
    project_id  TEXT REFERENCES projects (id) ON DELETE RESTRICT,
    revision    INTEGER NOT NULL CHECK (revision >= 1),
    PRIMARY KEY (device_id, face)
);

CREATE TABLE raw_events (
    id            TEXT PRIMARY KEY,
    device_id     TEXT NOT NULL REFERENCES devices (id) ON DELETE RESTRICT,
    kind          TEXT NOT NULL
                  CHECK (kind IN ('baseline', 'face_change', 'neutral',
                                  'disconnect', 'reconnect', 'invalid')),
    raw_value     INTEGER CHECK (raw_value IS NULL OR raw_value BETWEEN 0 AND 8),
    sequence      INTEGER NOT NULL CHECK (sequence >= 0),
    connection_id TEXT NOT NULL,
    received_at   TEXT NOT NULL,
    detail        TEXT
);
CREATE INDEX ix_raw_events_device_time ON raw_events (device_id, received_at);

CREATE TABLE sessions (
    id          TEXT PRIMARY KEY,
    activity_id TEXT NOT NULL REFERENCES activities (id) ON DELETE RESTRICT,
    project_id  TEXT REFERENCES projects (id) ON DELETE RESTRICT,
    device_id   TEXT REFERENCES devices (id) ON DELETE RESTRICT,
    started_at  TEXT NOT NULL,
    ended_at    TEXT,
    source      TEXT NOT NULL CHECK (source IN ('device', 'manual')),
    quality     TEXT NOT NULL CHECK (quality IN ('confirmed', 'uncertain')),
    note        TEXT,
    revision    INTEGER NOT NULL CHECK (revision >= 1),
    CHECK (ended_at IS NULL OR ended_at >= started_at),
    CHECK (source <> 'device' OR device_id IS NOT NULL)
);
CREATE INDEX ix_sessions_started ON sessions (started_at);
CREATE INDEX ix_sessions_activity ON sessions (activity_id);
-- MVP rule: at most ONE running session for the person. The constant expression makes
-- every running row collide with every other one.
CREATE UNIQUE INDEX ux_sessions_single_running ON sessions ((1)) WHERE ended_at IS NULL;

-- Defence in depth for the MVP rule "no overlapping personal sessions". A running session
-- counts as ending at the far future. Touching spans (end = start) are allowed.
CREATE TRIGGER trg_sessions_no_overlap_insert
BEFORE INSERT ON sessions
BEGIN
    SELECT RAISE(ABORT, 'sessions overlap')
    WHERE EXISTS (
        SELECT 1 FROM sessions s
        WHERE s.started_at < COALESCE(NEW.ended_at, '9999-12-31T23:59:59.999999Z')
          AND COALESCE(s.ended_at, '9999-12-31T23:59:59.999999Z') > NEW.started_at
    );
END;

CREATE TRIGGER trg_sessions_no_overlap_update
BEFORE UPDATE OF started_at, ended_at ON sessions
BEGIN
    SELECT RAISE(ABORT, 'sessions overlap')
    WHERE EXISTS (
        SELECT 1 FROM sessions s
        WHERE s.id <> NEW.id
          AND s.started_at < COALESCE(NEW.ended_at, '9999-12-31T23:59:59.999999Z')
          AND COALESCE(s.ended_at, '9999-12-31T23:59:59.999999Z') > NEW.started_at
    );
END;

CREATE TABLE corrections (
    id           TEXT PRIMARY KEY,
    session_id   TEXT NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
    field_name   TEXT NOT NULL,
    old_value    TEXT,
    new_value    TEXT,
    reason       TEXT NOT NULL CHECK (length(reason) >= 1),
    revision     INTEGER NOT NULL CHECK (revision >= 2),
    corrected_at TEXT NOT NULL
);
CREATE INDEX ix_corrections_session ON corrections (session_id);

-- Records destructive actions (session/entity deletion, restore) so they stay traceable.
CREATE TABLE audit_log (
    id        TEXT PRIMARY KEY,
    at        TEXT NOT NULL,
    action    TEXT NOT NULL,
    entity    TEXT NOT NULL,
    entity_id TEXT,
    detail    TEXT
);
CREATE INDEX ix_audit_log_at ON audit_log (at);
